package com.example.minicommerce.audit.infrastructure;
import jakarta.persistence.*;import java.time.Instant;
@Entity@Table(name="audit_log",indexes=@Index(name="ix_audit_resource",columnList="resource_type,resource_id,created_at"))public class AuditLogEntity{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="actor_id")private Long actorId;@Column(nullable=false,length=100)private String action;@Column(name="resource_type",nullable=false,length=100)private String resourceType;@Column(name="resource_id",nullable=false,length=100)private String resourceId;@Column(nullable=false,length=20)private String result;@Column(name="trace_id",length=128)private String traceId;@Column(name="before_json",columnDefinition="text")private String beforeJson;@Column(name="after_json",columnDefinition="text")private String afterJson;@Column(name="created_at",nullable=false)private Instant createdAt;protected AuditLogEntity(){}public AuditLogEntity(Long actorId,String action,String resourceType,String resourceId,String result,String traceId,String beforeJson,String afterJson,Instant createdAt){this.actorId=actorId;this.action=action;this.resourceType=resourceType;this.resourceId=resourceId;this.result=result;this.traceId=traceId;this.beforeJson=beforeJson;this.afterJson=afterJson;this.createdAt=createdAt;}}
